import fs from 'fs';
import path from 'path';

const ROOT = '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa';
const SRC = path.join(ROOT, 'overrides/app');
const EXT = ['.ts', '.tsx', '.js', '.jsx'];

const files = [];
(function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (EXT.includes(path.extname(e.name))) files.push(p);
  }
})(SRC);

const resolve = (from, spec) => {
  let base;
  if (spec.startsWith('.')) base = path.resolve(path.dirname(from), spec);
  else if (spec === 'app' || spec.startsWith('app/')) base = path.join(SRC, spec.slice(3));
  else return null;
  for (const e of EXT) { if (fs.existsSync(base + e)) return base + e; }
  for (const e of EXT) { const i = path.join(base, 'index' + e); if (fs.existsSync(i)) return i; }
  return null;
};

// value imports only — `import type` is erased and cannot cause a TDZ
const IMPORT_RE = /import\s+(?!type\s)(?:[\s\S]*?\s+from\s+)?['"]([^'"]+)['"]/g;
const graph = new Map();
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8');
  const deps = new Set();
  for (const m of src.matchAll(IMPORT_RE)) {
    const r = resolve(f, m[1]);
    if (r) deps.add(r);
  }
  graph.set(f, [...deps]);
}

const WHITE = 0, GREY = 1, BLACK = 2;
const colour = new Map(files.map(f => [f, WHITE]));
const stack = [];
const cycles = [];
function dfs(n) {
  colour.set(n, GREY); stack.push(n);
  for (const d of graph.get(n) || []) {
    if (colour.get(d) === GREY) cycles.push([...stack.slice(stack.indexOf(d)), d]);
    else if (colour.get(d) === WHITE) dfs(d);
  }
  stack.pop(); colour.set(n, BLACK);
}
for (const f of files) if (colour.get(f) === WHITE) dfs(f);

const rel = p => path.relative(ROOT, p);
if (!cycles.length) console.log('No value-import cycles found in overrides/app');
else {
  console.log(`${cycles.length} cycle(s):\n`);
  const seen = new Set();
  for (const c of cycles) {
    const key = [...c].sort().join('|');
    if (seen.has(key)) continue;
    seen.add(key);
    console.log(c.map(rel).join('\n  -> '));
    console.log('');
  }
}
EOF
