import fs from 'fs';
import path from 'path';

const ROOT = '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa';
const OVR = path.join(ROOT, 'overrides/app');
const BASE = path.join(ROOT, 'node_modules/@salesforce/retail-react-app/app');
const PKG = '@salesforce/retail-react-app/app/';
const EXT = ['.ts', '.tsx', '.js', '.jsx'];

const tryFile = (b) => {
  for (const e of EXT) if (fs.existsSync(b + e) && fs.statSync(b + e).isFile()) return b + e;
  for (const e of EXT) { const i = path.join(b, 'index' + e); if (fs.existsSync(i)) return i; }
  return null;
};

// ccExtensibility: a base-package path resolves to overrides/ when the mirrored file exists
const resolveBase = (sub) => tryFile(path.join(OVR, sub)) || tryFile(path.join(BASE, sub));

const resolve = (from, spec) => {
  if (spec.startsWith(PKG)) return resolveBase(spec.slice(PKG.length));
  if (spec === 'app' || spec.startsWith('app/')) {
    const sub = spec === 'app' ? '' : spec.slice(4);
    return tryFile(path.join(OVR, sub));
  }
  if (spec.startsWith('.')) {
    const abs = path.resolve(path.dirname(from), spec);
    // a relative import inside the base package is NOT redirected to overrides
    return tryFile(abs);
  }
  return null;
};

const IMPORT_RE = /import\s+(?!type\s)(?:[\s\S]*?\s+from\s+)?['"]([^'"]+)['"]/g;
const EXPORT_FROM_RE = /export\s+(?!type\s)(?:\*|\{[\s\S]*?\})\s+from\s+['"]([^'"]+)['"]/g;

const graph = new Map();
const load = (f) => {
  if (graph.has(f)) return;
  let src;
  try { src = fs.readFileSync(f, 'utf8'); } catch { graph.set(f, []); return; }
  const deps = new Set();
  for (const re of [IMPORT_RE, EXPORT_FROM_RE]) {
    for (const m of src.matchAll(re)) {
      const r = resolve(f, m[1]);
      if (r) deps.add(r);
    }
  }
  graph.set(f, [...deps]);
  for (const d of deps) load(d);
};

// entry: the PDP page as the build reaches it
const entry = resolveBase('pages/product-detail');
load(entry);

const WHITE=0, GREY=1, BLACK=2;
const colour = new Map();
const stack = [];
const cycles = [];
function dfs(n) {
  colour.set(n, GREY); stack.push(n);
  for (const d of graph.get(n) || []) {
    if (colour.get(d) === GREY) cycles.push([...stack.slice(stack.indexOf(d)), d]);
    else if ((colour.get(d) ?? WHITE) === WHITE) dfs(d);
  }
  stack.pop(); colour.set(n, BLACK);
}
dfs(entry);

const rel = p => p.replace(ROOT + '/', '').replace('node_modules/@salesforce/retail-react-app/app/', 'BASE:').replace('overrides/app/', 'OVR:');
console.log(`Modules reachable from PDP entry: ${graph.size}`);
console.log(`Entry: ${rel(entry)}\n`);
if (!cycles.length) { console.log('No cycles reachable from the PDP entry.'); }
else {
  const seen = new Set();
  const uniq = cycles.filter(c => { const k=[...c].sort().join('|'); if(seen.has(k)) return false; seen.add(k); return true; });
  console.log(`${uniq.length} unique cycle(s):\n`);
  for (const c of uniq.slice(0, 12)) console.log(c.map(rel).join('\n  -> ') + '\n');
  // highlight cycles that involve an override file
  const withOvr = uniq.filter(c => c.some(m => m.startsWith(OVR)));
  console.log(`\n=== ${withOvr.length} cycle(s) involve an overrides/ file ===\n`);
  for (const c of withOvr.slice(0, 12)) console.log(c.map(rel).join('\n  -> ') + '\n');
}
EOF
